'use strict';
const http=require('node:http'),fs=require('node:fs'),path=require('node:path'),{chromium}=require('playwright'),root=process.cwd();
const server=http.createServer((req,res)=>{const p=decodeURIComponent(new URL(req.url,'http://127.0.0.1').pathname),relative=p==='/'?'/experiments/change-journal-prototype/activity-session-manager-real-resume-diagnostic.html':p,file=path.resolve(root,'.'+relative);if(!file.startsWith(root+path.sep)||!fs.existsSync(file)||!fs.statSync(file).isFile()){res.writeHead(404);res.end('Not found');return;}res.writeHead(200,{'content-type':path.extname(file)==='.html'?'text/html; charset=utf-8':'text/javascript; charset=utf-8'});fs.createReadStream(file).pipe(res);});
(async()=>{let browser;try{await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(4182,'127.0.0.1',resolve);});browser=await chromium.launch({headless:true});const page=await browser.newPage();page.on('pageerror',e=>{throw e;});await page.goto('http://127.0.0.1:4182/',{waitUntil:'load'});await page.waitForFunction(()=>window.__activitySessionResumeDiagnostic&&window.__dictationResumeDiagnostic);const results=await page.evaluate(()=>({wordPuzzle:window.__activitySessionResumeDiagnostic,dictation:window.__dictationResumeDiagnostic}));const wp=results.wordPuzzle,di=results.dictation;if(wp.error||wp.reproduced!==7||wp.total!==7)throw Error('Expected 7 WordPuzzle transaction assertions; got '+JSON.stringify(wp));if(di.error||di.reproduced!==6||di.total!==6)throw Error('Expected 6 Dictation transaction assertions; got '+JSON.stringify(di));wp.results.forEach(x=>console.log('WORDPUZZLE PASS — '+x.name+' — '+x.detail));di.results.forEach(x=>console.log('DICTATION PASS — '+x.name+' — '+x.detail));console.log('ACTUAL ACTIVITY SESSION MANAGER TRANSACTIONS: PASS (WordPuzzle 7/7; Dictation 6/6; total 13/13)');}finally{if(browser)await browser.close();await new Promise(resolve=>server.close(resolve));}})().catch(e=>{console.error(e);process.exitCode=1;});